1	import React, { useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	import { useJsonResource } from '../../ui/useJsonResource';
4	
5	// Clients feature: add a client (name + email) and list every client. Opening a client
6	// (client-open-<id>) reveals the projects being done for them — the client's own projects listing,
7	// scoped via its /api/clients/<id>/projects endpoint. Owns its own state; talks to its own
8	// /api/clients endpoints. data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string; outstanding: number };
10	// How the clients list is ordered: alphabetically by name, or by how much each client still owes.
11	type SortKey = 'name' | 'outstanding';
12	type Project = { id: number; name: string; clientId: number; clientName: string };
13	type Contact = {
14	  id: number;
15	  clientId: number;
16	  name: string;
17	  email: string;
18	  role: string;
19	  primary: boolean;
20	};
21	type ClientSummary = { projectCount: number; contactCount: number };
22	type StatementInvoice = { id: number; projectId: number; amountDue: number };
23	type ClientStatement = { invoices: StatementInvoice[]; outstandingTotal: number };
24	
25	// Money, the way every invoice figure is shown across the app: a dollar sign and two decimals.
26	function money(amount: number): string {
27	  return `$${Number(amount).toLocaleString('en-US', {
28	    minimumFractionDigits: 2,
29	    maximumFractionDigits: 2,
30	  })}`;
31	}
32	
33	// Every client (and contact) needs a proper email. Same shape the server enforces (see CreateClient
34	// / CreateContact) so the UI and the API agree on what "valid" means.
35	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
36	function isValidEmail(value: string): boolean {
37	  return EMAIL_RE.test(value.trim());
38	}
39	
40	// A client's statement: all of their invoices in one place, each with what is still owed on it, and
41	// the total still owed across them all. Kept behind an opener so the client detail stays compact.
42	// Owns its own statement state, scoped to the one client it is showing; talks to that client's own
43	// /api/clients/<id>/statement endpoint.
44	function ClientStatement({ client }: { client: Client }) {
45	  const [statement] = useJsonResource<ClientStatement | null>(
46	    `/api/clients/${client.id}/statement`,
47	    null,
48	  );
49	  const [open, setOpen] = useState(false);
50	
51	  return (
52	    <section data-testid="client-statement">
53	      <button data-testid="client-statement-open" onClick={() => setOpen(true)}>
54	        Statement
55	      </button>
56	      {open && statement && (
57	        <>
58	          <table data-testid="client-statement-table">
59	            <tbody>
60	              {statement.invoices.map((inv) => (
61	                <tr key={inv.id} data-testid={`statement-invoice-row-${inv.id}`}>
62	                  <td data-testid="statement-invoice-due">{money(inv.amountDue)}</td>
63	                </tr>
64	              ))}
65	            </tbody>
66	          </table>
67	          <p data-testid="client-outstanding-total">{money(statement.outstandingTotal)}</p>
68	        </>
69	      )}
70	    </section>
71	  );
72	}
73	
74	// A client's at-a-glance counts: how many projects and contacts are kept for them. Owns its own
75	// summary state, scoped to the one client it is showing; talks to that client's own
76	// /api/clients/<id>/summary endpoint.
77	function ClientSummaryBadges({ client }: { client: Client }) {
78	  const [summary] = useJsonResource<ClientSummary>(`/api/clients/${client.id}/summary`, {
79	    projectCount: 0,
80	    contactCount: 0,
81	  });
82	
83	  return (
84	    <section data-testid="client-summary">
85	      <span data-testid="client-projects-count">{summary.projectCount}</span>
86	      <span data-testid="client-contacts-count">{summary.contactCount}</span>
87	    </section>
88	  );
89	}
90	
91	// The add-a-contact form: name, email and role, all required, with the same email check the server
92	// runs. Owns only its own field state and clears itself once the parent has taken the new contact.
93	function ContactForm({
94	  onAdd,
95	}: {
96	  onAdd: (contact: { name: string; email: string; role: string }) => Promise<void>;
97	}) {
98	  const [name, setName] = useState('');
99	  const [email, setEmail] = useState('');
100	  const [role, setRole] = useState('');
101	  const [emailError, setEmailError] = useState('');
102	
103	  async function submit(e: React.FormEvent) {
104	    e.preventDefault();
105	    if (!name.trim() || !email.trim() || !role.trim()) {
106	      return;
107	    }
108	    if (!isValidEmail(email)) {
109	      setEmailError('Enter a valid email address.');
110	      return;
111	    }
112	    setEmailError('');
113	    await onAdd({ name, email, role });
114	    setName('');
115	    setEmail('');
116	    setRole('');
117	  }
118	
119	  return (
120	    <form data-testid="contact-form" onSubmit={submit}>
121	      <input
122	        data-testid="contact-form-name"
123	        placeholder="Name"
124	        value={name}
125	        onChange={(e) => setName(e.target.value)}
126	      />
127	      <input
128	        data-testid="contact-form-email"
129	        placeholder="Email"
130	        value={email}
131	        onChange={(e) => setEmail(e.target.value)}
132	      />
133	      {emailError && (
134	        <p data-testid="contact-form-email-error" role="alert">
135	          {emailError}
136	        </p>
137	      )}
138	      <input
139	        data-testid="contact-form-role"
140	        placeholder="Role"
141	        value={role}
142	        onChange={(e) => setRole(e.target.value)}
143	      />
144	      <button data-testid="contact-form-submit" type="submit">
145	        Add contact
146	      </button>
147	    </form>
148	  );
149	}
150	
151	// The contacts list itself: a row per contact with a control to promote it to the client's primary.
152	function ContactsTable({
153	  contacts,
154	  onMakePrimary,
155	}: {
156	  contacts: Contact[];
157	  onMakePrimary: (id: number) => void;
158	}) {
159	  return (
160	    <table data-testid="client-contacts-table">
161	      <tbody>
162	        {contacts.map((ct) => (
163	          <tr key={ct.id} data-testid={`contact-row-${ct.id}`}>
164	            <td data-testid="contact-name">{ct.name}</td>
165	            <td data-testid="contact-email">{ct.email}</td>
166	            <td data-testid="contact-role">{ct.role}</td>
167	            <td>
168	              <button data-testid={`contact-primary-${ct.id}`} onClick={() => onMakePrimary(ct.id)}>
169	                Make primary
170	              </button>
171	            </td>
172	          </tr>
173	        ))}
174	      </tbody>
175	    </table>
176	  );
177	}
178	
179	// A client's contacts: the people the user keeps for them (name, email, role), with a form to add
180	// another. Owns its own contact state, scoped to the one client it is showing; talks to that
181	// client's own /api/clients/<id>/contacts endpoints. The form and the table are their own pieces so
182	// this stays a thin coordinator: load, add, promote, show who is primary.
183	function ClientContacts({ client }: { client: Client }) {
184	  const [contacts, reload] = useJsonResource<Contact[]>(`/api/clients/${client.id}/contacts`, []);
185	
186	  async function addContact(contact: { name: string; email: string; role: string }) {
187	    await fetch(`/api/clients/${client.id}/contacts`, {
188	      method: 'POST',
189	      headers: { 'Content-Type': 'application/json' },
190	      body: JSON.stringify(contact),
191	    });
192	    await reload();
193	  }
194	
195	  // Pick this contact as the client's one main contact, then refresh so the new primary shows.
196	  async function makePrimary(id: number) {
197	    await fetch(`/api/contacts/${id}/primary`, { method: 'POST' });
198	    await reload();
199	  }
200	
201	  const primary = contacts.find((ct) => ct.primary) ?? null;
202	
203	  return (
204	    <section data-testid="client-contacts">
205	      <p data-testid="client-primary-contact">{primary ? primary.name : ''}</p>
206	      <ContactForm onAdd={addContact} />
207	      <ContactsTable contacts={contacts} onMakePrimary={makePrimary} />
208	    </section>
209	  );
210	}
211	
212	// A client's detail: the projects being done for them. Owns its own project state, scoped to the one
213	// client it is showing. Reuses the project-row-<id>/project-name anchors in a client-scoped table.
214	// Shows only the client's ACTIVE projects by default (scope=active); the show-all toggle asks the
215	// server for everything (scope=all), so the finished and hidden (archived) ones appear too.
216	function ClientProjects({ client }: { client: Client }) {
217	  const [showAll, setShowAll] = useState(false);
218	  const [projects] = useJsonResource<Project[]>(
219	    `/api/clients/${client.id}/projects?scope=${showAll ? 'all' : 'active'}`,
220	    [],
221	  );
222	
223	  return (
224	    <section data-testid="client-projects">
225	      <button data-testid="client-projects-show-all" onClick={() => setShowAll((v) => !v)}>
226	        {showAll ? 'Show only active' : 'Show finished and hidden too'}
227	      </button>
228	      <table data-testid="client-projects-table">
229	        <tbody>
230	          {projects.map((p) => (
231	            <tr key={p.id} data-testid={`project-row-${p.id}`}>
232	              <td data-testid="project-name">{p.name}</td>
233	            </tr>
234	          ))}
235	        </tbody>
236	      </table>
237	    </section>
238	  );
239	}
240	
241	// A name-and-email form for a client, used to add one and reusable for correcting one. `testid` is
242	// the anchor prefix (its fields are `${testid}-name` / `-email` / `-email-error` / `-submit`), so a
243	// second instance (e.g. an edit form) just passes a different prefix. Validates the email format the
244	// way the server does; `onSubmit` returns an error string to show (e.g. a duplicate the server
245	// rejected) or null on success, in which case the form clears back to its initial values.
246	function ClientForm({
247	  testid,
248	  submitLabel,
249	  initial = { name: '', email: '' },
250	  onSubmit,
251	}: {
252	  testid: string;
253	  submitLabel: string;
254	  initial?: { name: string; email: string };
255	  onSubmit: (values: { name: string; email: string }) => Promise<string | null>;
256	}) {
257	  const [name, setName] = useState(initial.name);
258	  const [email, setEmail] = useState(initial.email);
259	  const [emailError, setEmailError] = useState('');
260	
261	  async function submit(e: React.FormEvent) {
262	    e.preventDefault();
263	    if (!isValidEmail(email)) {
264	      setEmailError('Enter a valid email address.');
265	      return;
266	    }
267	    const error = await onSubmit({ name, email });
268	    if (error) {
269	      setEmailError(error);
270	      return;
271	    }
272	    setEmailError('');
273	    setName(initial.name);
274	    setEmail(initial.email);
275	  }
276	
277	  return (
278	    <form data-testid={testid} onSubmit={submit}>
279	      <input
280	        data-testid={`${testid}-name`}
281	        placeholder="Name"
282	        value={name}
283	        onChange={(e) => setName(e.target.value)}
284	      />
285	      <input
286	        data-testid={`${testid}-email`}
287	        placeholder="Email"
288	        value={email}
289	        onChange={(e) => setEmail(e.target.value)}
290	      />
291	      {emailError && (
292	        <p data-testid={`${testid}-email-error`} role="alert">
293	          {emailError}
294	        </p>
295	      )}
296	      <button data-testid={`${testid}-submit`} type="submit">
297	        {submitLabel}
298	      </button>
299	    </form>
300	  );
301	}
302	
303	// The client list: a row per client with controls to open its detail or archive it.
304	function ClientsTable({
305	  clients,
306	  onOpen,
307	  onEdit,
308	  onArchive,
309	}: {
310	  clients: Client[];
311	  onOpen: (id: number) => void;
312	  onEdit: (id: number) => void;
313	  onArchive: (id: number) => void;
314	}) {
315	  return (
316	    <table data-testid="clients-table">
317	      <tbody>
318	        {clients.map((c) => (
319	          <tr key={c.id} data-testid={`client-row-${c.id}`}>
320	            <td data-testid="client-name">{c.name}</td>
321	            <td data-testid="client-email">{c.email}</td>
322	            <td data-testid="client-outstanding">{money(c.outstanding)}</td>
323	            <td>
324	              <button data-testid={`client-open-${c.id}`} onClick={() => onOpen(c.id)}>
325	                Open
326	              </button>
327	              <button data-testid={`client-edit-${c.id}`} onClick={() => onEdit(c.id)}>
328	                Edit
329	              </button>
330	              <button data-testid={`client-archive-${c.id}`} onClick={() => onArchive(c.id)}>
331	                Archive
332	              </button>
333	            </td>
334	          </tr>
335	        ))}
336	      </tbody>
337	    </table>
338	  );
339	}
340	
341	function ClientsPage() {
342	  const [clients, reload] = useJsonResource<Client[]>('/api/clients', []);
343	  // Client-side name filter: the list can get long, so a search box narrows it. Case-insensitive
344	  // substring match on the client name; an empty box shows everyone.
345	  const [search, setSearch] = useState('');
346	  // How the list is ordered: by name (default) or by how much each client owes (most first).
347	  const [sort, setSort] = useState<SortKey>('name');
348	  const [openId, setOpenId] = useState<number | null>(null);
349	  // Which client (if any) is being corrected: opening the edit form seeds it with that client's
350	  // current name and email so the user tweaks rather than retypes.
351	  const [editingId, setEditingId] = useState<number | null>(null);
