166	  async function save(li: EditItem) {
167	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
168	      return;
169	    }
170	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
