190	  async function submit(e: React.FormEvent) {
191	    e.preventDefault();
192	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
193	      return;
194	    }
195	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
196	      method: 'POST',
197	      headers: { 'Content-Type': 'application/json' },
198	      body: JSON.stringify({
199	        description,
200	        qty: Number(qty),
201	        unit,
202	        unitPrice: Number(unitPrice),
203	      }),
204	    });
205	    setDescription('');
206	    setQty('');
207	    setUnit('');
