213	  // The subtotal is the sum of the line items; the discount is that percentage taken off it. Sales
214	  // tax is then added on top of the discounted base (worked out after the discount), and the final
215	  // total is the subtotal less the discount plus that tax.
216	  const subtotal = items.reduce((sum, li) => sum + amountOf(li), 0);
217	  const discount = (subtotal * discountPct) / 100;
218	  const tax = ((subtotal - discount) * taxPct) / 100;
219	  const total = subtotal - discount + tax;
220	
221	  return (
