266	            </tr>
267	          ))}
268	        </tbody>
269	      </table>
270	
271	      <p data-testid="invoice-subtotal">{money(subtotal)}</p>
272	      <p data-testid="invoice-discount">{money(discount)}</p>
273	      <p data-testid="invoice-tax">{money(tax)}</p>
274	      <p data-testid="invoice-amount">{money(total)}</p>
275	
276	      <form data-testid="lineitem-form" onSubmit={submit}>
