380	// The invoices raised against a project: what they add up to, a form to raise another, and a drill-in
381	// to each invoice's line items and payments. Owns its own invoice state, scoped to the one project.
382	// Whenever the invoices change (a new one raised, a status moved, a line item edited) the owner is
383	// told so figures derived from them — the budget's invoiced/remaining — can be refreshed.
384	function ProjectInvoices({
385	  projectId,
386	  onInvoicesChanged,
387	  openInvoiceId,
388	  setOpenInvoiceId,
389	}: {
390	  projectId: number;
391	  onInvoicesChanged: () => void;
392	  openInvoiceId: number | null;
393	  setOpenInvoiceId: (id: number | null) => void;
394	}) {
395	  const [invoices, setInvoices] = useState<Invoice[]>([]);
396	  const [amount, setAmount] = useState('');
397	  const [amountError, setAmountError] = useState('');
398	  const [sortByDue, setSortByDue] = useState(false);
399	
400	  async function load() {
401	    const res = await fetch(`/api/invoices?projectId=${projectId}`);
402	    setInvoices(await res.json());
403	    onInvoicesChanged();
404	  }
405	
406	  useEffect(() => {
407	    void load();
408	  }, [projectId]);
409	
410	  async function submit(e: React.FormEvent) {
411	    e.preventDefault();
412	    const value = Number(amount);
413	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
414	      setAmountError('Amount must be more than zero');
415	      return;
416	    }
417	    setAmountError('');
418	    await fetch('/api/invoices', {
419	      method: 'POST',
420	      headers: { 'Content-Type': 'application/json' },
421	      body: JSON.stringify({ projectId, amount: value }),
422	    });
423	    setAmount('');
424	    await load();
425	  }
426	
427	  // A lifecycle move (send, mark paid, …) is a POST to the matching action route followed by a reload;
428	  // routing them through one place means a new action is one more call site, not new plumbing.
429	  async function transition(id: number, action: 'send' | 'pay' | 'cancel') {
430	    await fetch(`/api/invoices/${id}/${action}`, { method: 'POST' });
431	    await load();
432	  }
433	
434	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
435	  const shownInvoices = sortByDue
436	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
437	    : invoices;
438	
439	  return (
440	    <>
441	      <form data-testid="invoice-form" onSubmit={submit}>
442	        <input
443	          data-testid="invoice-form-amount"
444	          placeholder="Amount"
445	          value={amount}
446	          onChange={(e) => setAmount(e.target.value)}
447	        />
448	        <button data-testid="invoice-form-submit" type="submit">
449	          Add invoice
450	        </button>
451	        {amountError && (
452	          <p data-testid="invoice-form-amount-error" role="alert">
453	            {amountError}
454	          </p>
455	        )}
456	      </form>
457	
458	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
459	        Sort by due date
460	      </button>
461	
462	      {openInvoiceId === null ? (
463	        <>
464	          <table data-testid="project-invoices-table">
465	            <tbody>
466	              {shownInvoices.map((inv) => (
467	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
468	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
469	                  <td data-testid="invoice-due-amount">{money(inv.amountDue)}</td>
470	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
471	                  <td data-testid="invoice-due">{inv.dueDate}</td>
472	                  <td data-testid="invoice-status">{inv.status}</td>
473	                  <td>
474	                    <InvoiceActions
475	                      invoice={inv}
476	                      onOpen={() => setOpenInvoiceId(inv.id)}
477	                      onSend={() => transition(inv.id, 'send')}
478	                      onPay={() => transition(inv.id, 'pay')}
479	                      onCancel={() => transition(inv.id, 'cancel')}
480	                    />
481	                  </td>
482	                </tr>
483	              ))}
484	            </tbody>
485	          </table>
486	
487	          <p data-testid="project-invoices-total">{money(total)}</p>
488	        </>
489	      ) : (
490	        <InvoiceDetail
491	          invoiceId={openInvoiceId}
492	          onChange={load}
493	          onClose={() => setOpenInvoiceId(null)}
494	        />
495	      )}
496	    </>
497	  );
498	}
