1	package net.officefloor.hq.app.invoice;
2	
3	import java.math.BigDecimal;
4	import net.officefloor.server.http.HttpException;
5	import net.officefloor.server.http.HttpStatus;
6	import net.officefloor.web.HttpPathParameter;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.jdbc.core.JdbcTemplate;
9	
10	/**
11	 * GET /api/invoices/{id} — one invoice, with its amount (sum of line items), the amount still due
12	 * (that less everything paid), and its status worked out from the payments recorded against it.
13	 */
14	public class GetInvoice {
15	
16	    public void service(@HttpPathParameter("id") String id, JdbcTemplate jdbc,
17	            ObjectResponse<InvoiceView> response) {
18	        // The amount is the subtotal (sum of line items) less its discount, then with sales tax
19	        // added on top of that discounted base — tax is worked out after the discount. The amount
20	        // due is that same taxed amount less everything paid against it.
21	        InvoiceView invoice = jdbc.query(
22	                "SELECT id, project_id, status, issued_date, due_date, discount_pct, tax_pct, "
23	                        + "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li "
24	                        + "WHERE li.invoice_id = invoices.id), 0) * (100 - discount_pct) / 100 "
25	                        + "* (100 + tax_pct) / 100 AS amount, "
26	                        + "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li "
27	                        + "WHERE li.invoice_id = invoices.id), 0) * (100 - discount_pct) / 100 "
