4	// `reload` for callers that mutate the resource and need to pull the fresh version. Feature panels
5	// read one url this way, so this shared primitive is where that fetch-into-state pattern lives once.
6	export function useJsonResource<T>(url: string, initial: T): [T, () => Promise<void>] {
